/* Teacher monitoring reads the same Firebase evidence students submit.
 * Feedback is separate from the protected rubric/official grade records. */
const G11Monitor=(()=>{
 let feedbackDrafts={},progress={},accounts={},selected='',filter='all',started=false;
 const esc=s=>escHtml(String(s??''));
 const pairs=[['intro',['tn-webcam-image-classification','tn-card-sorting-activity']],['train',['tn-machine-learning-image-classification','tn-image-upload-classifier']],['live',['tn-webcam-live-classifier','tn-webcam-live-classifier-coding-project','tn-adjustable-accuracy-webcam-classifier']],['music',['tn-responsive-instrument','tn-music-generator']],['chess',['tn-ai-chess-player']],['assistant',['tn-ai-digital-assistant']],['rescue',['tn-ai-animal-rescue']],['navigation',['tn-ai-navigation-algorithm']],['auto',['tn-ai-auto-navigation']],['finish',['tn-ai-find-the-finish-line']]];
 const map=Object.fromEntries(pairs);
 function sources(id){if(id.startsWith('g11AiCompletion_'))return (map[id.replace('g11AiCompletion_','')]||[]).map(n=>['projects',n]);return [["lessons",{g11AiFormative1:1,g11AiFormative2:4,g11AiFormative3:13,g11AiSummative:14}[id]]].filter(([,key])=>key);}
 function version(studentId,id){return sources(id).map(([kind,key])=>kind+'/'+key+':'+(progress[studentId]?.student?.[kind]?.[key]?.revision||0)).join('|');}
 function pendingCount(id){const row=progress[id]||{},entries=[...Object.entries(row.student?.projects||{}).map(([k,v])=>['p_'+k,v,v.ready]),...Object.entries(row.student?.lessons||{}).filter(([k])=>['1','4','13','14'].includes(k)).map(([k,v])=>['l_'+k,v,v.done])];return entries.filter(([key,v,ready])=>ready&&(!row.teacher?.reviews?.[key]||row.teacher.reviews[key].sourceRevision!==v.revision||row.teacher.reviews[key].status==='needs_revision')).length;}
 function checkStale(){if(typeof dcTeacherState==='undefined'||dcTeacherState.grade!==11||dcTeacherState.quarter!==2)return;const draft=dcTeacherState.draft;let changed=false;for(const a of G11_AI_WEIGHTED_ASSESSMENTS){const known=draft.evidenceVersions?.[a.id];if(draft.reviewed?.[a.id]===true&&known!==undefined&&known!==version(dcTeacherState.studentId,a.id)){draft.reviewed[a.id]=false;changed=true;}}if(changed){dcTeacherState.dirty=true;renderDcAssessmentPanel();showAlert('Siswa mengirim versi bukti baru. Periksa kembali komponen yang berubah; nilai resmi terakhir tetap tersedia.','warning');}}
 function render(){const root=document.getElementById('g11MonitorList');if(!root)return;const classFilter=document.getElementById('g11MonitorClass')?.value||'',query=(document.getElementById('g11MonitorSearch')?.value||'').toLowerCase();const students=allSiswa.filter(s=>getTeacherStudentGrade(s)===11&&(!classFilter||s.kelas===classFilter)&&String(s.nama).toLowerCase().includes(query)&&(filter!=='pending'||pendingCount(s.id)>0));const classes=[...new Set(allSiswa.filter(s=>getTeacherStudentGrade(s)===11).map(s=>s.kelas))];const choice=document.getElementById('g11MonitorClass');if(choice&&choice.options.length<=1){choice.innerHTML='<option value="">Semua kelas 11</option>'+classes.map(c=>'<option>'+esc(c)+'</option>').join('');}
 root.innerHTML=students.map(s=>{const row=progress[s.id]?.student||{},ready=Object.values(row.projects||{}).filter(r=>r.ready).length,count=pendingCount(s.id);return '<article class="g11-monitor-row"><div><b>'+esc(s.nama)+'</b><small>'+esc(s.kelas)+' · '+ready+'/15 proyek diajukan · '+count+' menunggu pemeriksaan</small><p>'+esc(row.target?.goal ? (row.target.date+' · '+row.target.goal) : 'Belum ada target yang dikirim')+'</p></div><div><button type="button" data-student="'+esc(s.id)+'" class="dc-save-button g11-monitor-open">Lihat bukti & nilai</button>'+(!accounts[s.id]?.uid?'<button type="button" data-student="'+esc(s.id)+'" class="dc-save-button g11-monitor-activate">Aktifkan akun cloud</button>':'<small>Akun cloud aktif</small>')+'</div></article>';}).join('')||'<p class="g11-monitor-empty">Belum ada siswa yang sesuai filter.</p>';root.querySelectorAll('.g11-monitor-open').forEach(b=>b.addEventListener('click',()=>open(b.dataset.student)));root.querySelectorAll('.g11-monitor-activate').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{await G11CloudIdentity.activate(allSiswa.find(s=>s.id===b.dataset.student));showAlert('Akun cloud aktif. Siswa dapat masuk dengan password CS.Report yang sama.','success');}catch(e){showAlert(e.message,'danger');}finally{b.disabled=false;}}));renderEvidence();}
 function open(id){if(dcTeacherState.saving)return;if(dcTeacherState.dirty&&!window.confirm('Ada rubrik yang belum disimpan. Tetap membuka siswa ini?'))return;dcTeacherState.dirty=false;changeDcAssessmentGrade(11);setQuarter(2);selected=id;dcTeacherState.studentId=id;document.getElementById('dcAssessmentStudent').value=id;loadDcAssessmentDraft();renderEvidence();document.getElementById('dcAssessmentPanel').scrollIntoView({behavior:'smooth'});}
 function proofLinks(value){return [...new Set(String(value||'').match(/https?:\/\/[^\s<>"']+/g)||[])].slice(0,5).map(u=>'<a class="dc-save-button" href="'+esc(u)+'" target="_blank" rel="noopener noreferrer">Buka tautan bukti ↗</a>').join(' ');}
 function evidenceHTML(studentId,assessmentId){const row=progress[studentId]||{},related=sources(assessmentId);return related.map(([kind,key])=>{const data=row.student?.[kind]?.[key],reviewKey=(kind==='projects'?'p_':'l_')+key,r=feedbackDrafts[studentId+'/'+reviewKey]||row.teacher?.reviews?.[reviewKey],label=kind==='projects'?key.replace(/^tn-/,'').replaceAll('-',' '):'Bukti '+(assessmentId.replace('g11Ai','')),isReady=kind==='projects'?data?.ready:data?.done;return '<article class="g11-evidence"><b>'+esc(label)+'</b><small>'+(!data?'Belum dikirim':isReady?'Diajukan · revisi '+data.revision:'Draft · revisi '+data.revision)+'</small><p class="g11-evidence-text">'+esc(data?.evidence||'Belum ada bukti.')+'</p>'+proofLinks(data?.evidence)+(data?.reflection?'<p class="g11-evidence-text">'+esc(data.reflection)+'</p>':'')+'<label>Feedback guru<textarea maxlength="2000" id="g11-feedback-'+reviewKey+'">'+esc(r?.message||'')+'</textarea></label><label>Status pemeriksaan<select id="g11-status-'+reviewKey+'"><option value="seen">Sudah dilihat</option><option value="needs_revision" '+(r?.status==='needs_revision'?'selected':'')+'>Perlu revisi</option><option value="accepted" '+(r?.status==='accepted'?'selected':'')+'>Diterima</option></select></label><button type="button" data-revision="'+(data?.revision||0)+'" data-key="'+reviewKey+'" data-kind="'+kind+'" data-source="'+key+'" class="dc-save-button g11-feedback-save">Kirim feedback</button></article>';}).join('');}
 function renderEvidence(){const target=document.getElementById('g11EvidencePanel');if(!target||dcTeacherState.grade!==11||dcTeacherState.quarter!==2)return;const id=dcTeacherState.studentId;if(target.contains(document.activeElement))return;target.innerHTML='<h4>Bukti siswa dari Firebase</h4>'+evidenceHTML(id,dcTeacherState.selectedAssessmentId);target.querySelectorAll('.g11-feedback-save').forEach(b=>{const remember=()=>{feedbackDrafts[id+'/'+b.dataset.key]={message:document.getElementById('g11-feedback-'+b.dataset.key).value,status:document.getElementById('g11-status-'+b.dataset.key).value};};document.getElementById('g11-feedback-'+b.dataset.key).addEventListener('input',remember);document.getElementById('g11-status-'+b.dataset.key).addEventListener('change',remember);});target.querySelectorAll('.g11-feedback-save').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{const teacher=await G11CloudIdentity.verifyTeacher(),source=progress[id]?.student?.[b.dataset.kind]?.[b.dataset.source];await db.ref('learningProgress').child(id).child('grade11Ai/teacher/reviews').child(b.dataset.key).set({message:document.getElementById('g11-feedback-'+b.dataset.key).value,status:document.getElementById('g11-status-'+b.dataset.key).value,sourceRevision:Number(b.dataset.revision)||0,updatedAt:G11CloudIdentity.stamp(),updatedBy:teacher.uid});delete feedbackDrafts[id+'/'+b.dataset.key];showAlert('Feedback terkirim ke siswa. Nilai diisi dan disimpan melalui rubrik.','success');}catch(e){showAlert('Feedback belum terkirim: '+e.message,'danger');}finally{b.disabled=false;}}));}
 function mount(){const panel=document.getElementById('g11MonitorPanel');if(!panel)return;document.getElementById('g11MonitorSearch').addEventListener('input',render);document.getElementById('g11MonitorClass').addEventListener('change',render);document.getElementById('g11MonitorFilter').addEventListener('change',e=>{filter=e.target.value;render();});}
 function start(){if(started)return;started=true;mount();db.ref('grade11AiAccounts').on('value',snap=>{accounts=snap.val()||{};render();},e=>showAlert('Monitor akun cloud: '+e.message,'danger'));}
 return {invalidateStale:checkStale,start,render,renderEvidence,version,sources,onProgress(value){progress={};for(const [id,row]of Object.entries(value||{}))if(row.grade11Ai)progress[id]=row.grade11Ai;checkStale();render();}};
})();
